--- connectionStoreHome.ts ---
/**
 * El hogar del store de conexiones de proveedor y su apertura. Cuelga del
 * hogar de configuración de thyrox (`resolveDataDir`) en vez de componer
 * uno propio por plataforma, como hace OmniRoute con `DATA_DIR`;
 * `THYROX_PROVIDERS_DATA_DIR` lo declara aparte y vacía no cuenta.
 *
 * El directorio se crea sólo para el dueño: la base guarda credenciales, y las
 * cifra con la clave que el entorno declare (`fieldCipherFromEnv`).
 *
 * Porte de `omniroute: bin/cli/data-dir.mjs` y `bin/cli/sqlite.mjs` (MIT).
 */
import { Database } from 'bun:sqlite'
import fs from 'node:fs'
import { join } from 'node:path'

import { resolveDataDir } from '@thyrox/config/env/configHome'

import { createConnectionStore, type ConnectionStore } from './connectionStore.ts'
import { fieldCipherFromEnv } from './fieldCipher.ts'

export const PROVIDERS_DATA_SUBDIR = 'providers'
export const CONNECTIONS_DB_FILE = 'connections.sqlite3'
const OWNER_ONLY = 0o700

export function resolveProvidersDataDir(env: Record<string, string | undefined> = process.env): string {
  return resolveDataDir('THYROX_PROVIDERS_DATA_DIR', PROVIDERS_DATA_SUBDIR, env)
}

export interface OpenedConnectionStore {
  store: ConnectionStore
  close(): void
}

/** Abre (y crea si falta) el store del hogar de proveedores; quien lo abre lo cierra. */
export function openConnectionStore(options: { env?: Record<string, string | undefined>; report?: (message: string) => void } = {}): OpenedConnectionStore {
  const env = options.env ?? process.env
  const dir = resolveProvidersDataDir(env)
  fs.mkdirSync(dir, { recursive: true, mode: OWNER_ONLY })
  fs.chmodSync(dir, OWNER_ONLY)
  const db = new Database(join(dir, CONNECTIONS_DB_FILE), { create: true })
  const store = createConnectionStore({ db, cipher: fieldCipherFromEnv(env, options.report) })
  return { store, close: () => db.close() }
}
--- generateStorageKey.ts ---
#!/usr/bin/env bun
/**
 * Genera `THYROX_STORAGE_ENCRYPTION_KEY` — el secreto que
 * `accounts/fieldCipher.ts` deriva con scrypt para cifrar las credenciales
 * guardadas. `fieldCipher.ts` acepta cualquier cadena no vacía como secreto
 * (`declared = secret?.trim() ? secret : undefined`); este generador produce
 * 32 bytes aleatorios en hexadecimal, con la misma entropía que
 * `KEY_LENGTH` deriva para la clave AES-256 real.
 *
 *   bun bin/generateStorageKey.ts [--env-file <ruta>]
 *
 * Sin `--env-file`, el `.env` de la raíz de thyrox (`@thyrox/paths/reach.ts:
 * thyroxRoot`). Si la variable YA está declarada con un valor no vacío en ese
 * archivo, rehúsa y deja el archivo intacto: rotarla dejaría huérfanas las
 * conexiones que esa clave ya cifró. La clave nunca se imprime, ni por stdout
 * ni por stderr.
 *
 *   bun bin/generateStorageKey.ts --rotate [--env-file <ruta>]
 *
 * `--rotate` reemplaza una clave ya declarada: recifra con la nueva las
 * credenciales del store de conexiones (`rotateStorageKey`, en una sola
 * transacción) y sólo entonces publica el `.env` nuevo, escrito antes a un
 * archivo hermano y movido encima. Si el store rehúsa, el `.env` no cambia;
 * si el `.env` no se puede publicar, el store vuelve a la clave anterior.
 *
 * Salidas: 0 escrita o rotada · 1 la variable ya está declarada (sin
 * `--rotate`), no hay clave que rotar, o el store rehusó · 2 invocación
 * inválida (falta el valor de `--env-file`, o no se pudo derivar la raíz de
 * thyrox para el valor por defecto), o el `.env` rotado no se pudo publicar.
 */
import { randomBytes } from 'node:crypto'
import { Database } from 'bun:sqlite'
import { existsSync, readFileSync, renameSync, rmSync, statSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'
import { thyroxRoot } from '@thyrox/paths/reach.ts'

import { CONNECTIONS_DB_FILE, resolveProvidersDataDir } from '../src/accounts/connectionStoreHome.ts'
import { STORAGE_KEY_VARIABLE } from '../src/accounts/fieldCipher.ts'
import { rotateStorageKey, type RotationOutcome } from '../src/accounts/storageKeyRotation.ts'

const KEY_BYTES = 32

/** 32 bytes aleatorios en hex: el mismo tamaño que `KEY_LENGTH` deriva para AES-256. */
function generateKey(): string {
  return randomBytes(KEY_BYTES).toString('hex')
}

function defaultEnvFilePath(): string {
  return join(thyroxRoot(), '.env')
}

function arg(argv: string[], name: string): string | undefined {
  const i = argv.indexOf(`--${name}`)
  return i >= 0 ? argv[i + 1] : undefined
}

/**
 * El valor ya declarado de la variable en `path`, o `null` si no hay
 * archivo, no hay línea para ella, o su valor está en blanco — un valor en
 * blanco no cifró nada todavía, así que completarlo no rota ninguna clave en
 * uso.
 */
function declaredValue(path: string, name: string): string | null {
  if (!existsSync(path)) return null
  for (const line of readFileSync(path, 'utf8').split('\n')) {
    if (declaredName(line) !== name) continue
    const value = line.slice(line.indexOf('=') + 1).trim()
    if (value) return value
  }
  return null
}

/** El nombre que declara `line`, sin `export ` ni espacios, o `null` si no declara nada. */
function declaredName(line: string): string | null {
  let body = line.trim()
  if (!body || body.startsWith('#')) return null
  if (body.startsWith('export ')) body = body.slice('export '.length).trimStart()
  const cut = body.indexOf('=')
  return cut === -1 ? null : body.slice(0, cut).trim()
}

/**
 * Escribe la clave: completa en su sitio una declaración en blanco, o añade
 * la línea al final si la variable no está declarada. `declaredValue` ya
 * descartó el caso de un valor no vacío.
 */
function writeKey(path: string, key: string): void {
  const declaration = `${STORAGE_KEY_VARIABLE}=${key}`
  const existing = existsSync(path) ? readFileSync(path, 'utf8') : ''
  const lines = existing.split('\n')
  const blank = lines.findIndex(line => declaredName(line) === STORAGE_KEY_VARIABLE)
  if (blank !== -1) {
    lines[blank] = declaration
    writeFileSync(path, lines.join('\n'))
    return
  }
  const withNewline = existing.length > 0 && !existing.endsWith('\n') ? `${existing}\n` : existing
  writeFileSync(path, `${withNewline}${declaration}\n`)
}

/** El contenido de `existing` con la declaración de la variable apuntando a `key`. */
function withKeyReplaced(existing: string, key: string): string {
  return existing
    .split('\n')
    .map(line => (declaredName(line) === STORAGE_KEY_VARIABLE ? `${STORAGE_KEY_VARIABLE}=${key}` : line))
    .join('\n')
}

function describeRefusal(outcome: Exclude<RotationOutcome, { kind: 'rotated' }>): string {
  if (outcome.reason === 'undecryptable') {
    return `la conexión ${outcome.connectionId} guarda en ${outcome.column} un valor que la clave declarada no descifra`
  }
  if (outcome.reason === 'verification') {
    return `la clave nueva no devolvió el valor de ${outcome.connectionId}.${outcome.column}; la transacción se deshizo`
  }
  return outcome.reason === 'same-key' ? 'la clave nueva coincide con la anterior' : 'falta una de las dos claves'
}

export interface GenerateStorageKeyDeps {
  /** Publica el `.env` rotado; se inyecta para probar el camino en que falla. */
  rename?: (from: string, to: string) => void
}

function rotate(envFile: string, deps: GenerateStorageKeyDeps): number {
  const previous = declaredValue(envFile, STORAGE_KEY_VARIABLE)
  if (previous === null) {
    process.stderr.write(`${STORAGE_KEY_VARIABLE} no está declarada en ${envFile}: no hay clave que rotar.\n`)
    return 1
  }
  const next = generateKey()
  const staged = `${envFile}.rotating`
  writeFileSync(staged, withKeyReplaced(readFileSync(envFile, 'utf8'), next), { mode: statSync(envFile).mode })

  const storePath = join(resolveProvidersDataDir(process.env), CONNECTIONS_DB_FILE)
  const db = existsSync(storePath) ? new Database(storePath) : null
  try {
    const outcome: RotationOutcome = db ? rotateStorageKey(db, previous, next) : { kind: 'rotated', fields: 0 }
    if (outcome.kind === 'refused') {
      rmSync(staged, { force: true })
      process.stderr.write(`No se rota ${STORAGE_KEY_VARIABLE}: ${describeRefusal(outcome)}. ${envFile} y el store quedan intactos.\n`)
      return 1
    }
    try {
      ;(deps.rename ?? renameSync)(staged, envFile)
    } catch (error) {
      const restored = db ? rotateStorageKey(db, next, previous) : ({ kind: 'rotated', fields: 0 } as const)
      if (restored.kind === 'rotated') {
        rmSync(staged, { force: true })
        process.stderr.write(`No se pudo publicar ${envFile} (${(error as Error).message}); el store volvió a la clave anterior.\n`)
      } else {
        process.stderr.write(
          `No se pudo publicar ${envFile} (${(error as Error).message}) ni devolver el store a la clave anterior: ` +
            `la clave vigente está en ${staged}, no lo borres.\n`,
        )
      }
      return 2
    }
    process.stdout.write(`${STORAGE_KEY_VARIABLE} rotada en ${envFile}: ${outcome.fields} credencial(es) recifrada(s)\n`)
    return 0
  } finally {
    db?.close()
  }
}

export function main(argv: string[], deps: GenerateStorageKeyDeps = {}): number {
  let envFile: string
  const declared = arg(argv, 'env-file')
  if (argv.includes('--env-file') && declared === undefined) {
    process.stderr.write('--env-file requiere una ruta.\n')
    return 2
  }
  try {
    envFile = declared ?? defaultEnvFilePath()
  } catch (error) {
    process.stderr.write(`${(error as Error).message}\n`)
    return 2
  }

  if (argv.includes('--rotate')) return rotate(envFile, deps)

  if (declaredValue(envFile, STORAGE_KEY_VARIABLE) !== null) {
    process.stderr.write(
      `${STORAGE_KEY_VARIABLE} ya está declarada en ${envFile}: no se rota, ` +
        'dejaría huérfanas las conexiones que esa clave ya cifró.\n',
    )
    return 1
  }

  writeKey(envFile, generateKey())
  process.stdout.write(`${STORAGE_KEY_VARIABLE} escrita en ${envFile}\n`)
  return 0
}

if (import.meta.main) {
  process.exit(main(process.argv.slice(2)))
}
--- finding/index.ts ---
/**
 * El registro de hallazgos: de la fila del store al `.rst` y a su entrada en
 * el índice de la iniciativa.
 *
 * Vocabulario, porque las tres cosas se confundían bajo «hallazgo»:
 *
 * - **finding** — la conclusión de un análisis: algo que existe o sucedió.
 * - **record** — su fila en `findings_history`: el asiento administrativo.
 * - **entry** — su línea en el `index.rst` de la iniciativa: la fila de la
 *   tabla y el nombre en el toctree.
 *
 * Por qué es un paquete propio: `@thyrox/store` abre la base y
 * `@thyrox/paths` construye la ruta (`findingPath`), y ninguno sabe qué es un
 * hallazgo. Es la misma partición que `@thyrox/task` hace para las tareas.
 *
 * Un hallazgo publicado es evidencia fechada: `writeFinding` no escribe sobre
 * un archivo que ya existe.
 */
import { Database } from 'bun:sqlite'
import { existsSync, globSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { basename, dirname, join } from 'node:path'
import { findingPath, type Submodule } from '@thyrox/paths/docs.ts'

export type FindingRecord = {
  findingId: string
  submodule: Submodule
  initiative: string
  severity: string | null
  summary: string
  content: string
  sourceRef: string | null
}

const AUTHOR = 'Equipo Kaupamex'

/** El resumen en kebab-case ASCII: sin acentos ni signos. */
export function slugOf(summary: string): string {
  return summary
    .normalize('NFKD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
}

/** La fila de `findingId`, o `null` si el store no la tiene. Abre en sólo lectura. */
export function readFindingRecord(storeFile: string, findingId: string): FindingRecord | null {
  if (!existsSync(storeFile)) return null
  const db = new Database(storeFile, { readonly: true })
  try {
    const found = db
      .query(
        'SELECT finding_id, submodule, initiative, severity, summary, content, source_ref ' +
          'FROM findings_history WHERE finding_id = ?',
      )
      .get(findingId) as Record<string, string | null> | null
    if (!found) return null
    // Una capa desconocida la rechaza `findingPath`: su prefijo no casa con el ID.
    return {
      findingId: found.finding_id!,
      submodule: found.submodule as Submodule,
      initiative: found.initiative!,
      severity: found.severity,
      summary: found.summary!,
      content: found.content!,
      sourceRef: found.source_ref,
    }
  } finally {
    db.close()
  }
}

export type RenderOptions = {
  /** `repo@hash` del commit que lo resuelve; sin él, queda documentado. */
  resolvedIn?: string
  /** Cuerpo `.rst` que se copia tal cual tras la ficha. */
  body?: string
  /** Por defecto, el instante UTC al segundo. */
  createdAt?: string
}

function utcNow(): string {
  return new Date().toISOString().slice(0, 19)
}

/** `<alias>: <ruta>` al principio: la ruta ya dice de qué árbol es. */
const DECLARED_ALIAS = /^[a-z0-9][a-z0-9-]*: /

/**
 * La ruta con el alias de su árbol. Si la fila ya lo declara, se respeta: un
 * hallazgo de la capa `thyrox` puede citar un archivo de `kaupamex-docs`.
 */
function qualifiedSource(record: FindingRecord): string {
  const source = record.sourceRef ?? ''
  return DECLARED_ALIAS.test(source) ? source : `${record.submodule}: ${source}`
}

/** El documento con la plantilla B de `hallazgos-documentacion-obligatoria.md`. */
export function renderFinding(record: FindingRecord, options: RenderOptions): string {
  const createdAt = options.createdAt ?? utcNow()
  const title = `${record.findingId} — ${record.summary}`
  const lines = [
    '.. meta::',
    `   :fecha_creacion: ${createdAt}`,
    `   :autor: ${AUTHOR}`,
    `   :estado: ${options.resolvedIn ? 'resuelto' : 'documentado'}`,
    `   :submodulo: ${record.submodule}`,
    `   :iniciativa: ${record.initiative}`,
    '',
    `.. _${record.findingId.toLowerCase()}:`,
    '',
    title,
    '='.repeat(title.length),
    '',
    `- **Severidad:** ${record.severity ?? 'SIN DECLARAR'}`,
    `- **Fecha:** ${createdAt}`,
  ]
  if (record.sourceRef) lines.push(`- **Archivo:** \`\`${qualifiedSource(record)}\`\``)
  lines.push(
    `- **Descripcion:** ${record.content}`,
    `- **Estado:** ${options.resolvedIn ? `RESUELTO en \`\`${options.resolvedIn}\`\`` : 'DOCUMENTADO (sin fix inmediato)'}`,
    '',
  )
  let text = lines.join('\n')
  if (options.body) text += '\n' + options.body.replace(/\n+$/, '') + '\n'
  return text
}

/** Dónde vive el `.rst` de este hallazgo. */
export function findingFile(record: FindingRecord): string {
  return findingPath(record.submodule, record.initiative, record.findingId, slugOf(record.summary))
}

/** Escribe el `.rst`; `null` si ya existía (y entonces no lo toca). */
export function writeFinding(record: FindingRecord, options: RenderOptions): string | null {
  const target = findingFile(record)
  if (existsSync(target)) return null
  mkdirSync(dirname(target), { recursive: true })
  writeFileSync(target, renderFinding(record, options))
  return target
}

/**
 * La entrada del hallazgo en el índice: su fila tras la última de la tabla y
 * su nombre tras el último del toctree. Si ya estaba, el texto no cambia.
 */
export function addIndexEntry(index: string, record: FindingRecord, documentName: string, state: string): string {
  const lines = index.split('\n')
  const label = record.findingId.toLowerCase()
  if (!index.includes(`:ref:\`${label}\``)) {
    let lastRowEnd = -1
    lines.forEach((line, i) => {
      // Una fila empieza con `* -`; sus celdas siguen, contiguas, con `-`.
      const startsRow = line.startsWith('   * - ')
      const continuesRow = lastRowEnd === i - 1 && line.startsWith('     - ')
      if (startsRow || continuesRow) lastRowEnd = i
    })
    if (lastRowEnd < 0) throw new Error('el índice no tiene list-table')
    lines.splice(lastRowEnd + 1, 0,
      `   * - :ref:\`${label}\``, `     - ${record.severity ?? 'SIN DECLARAR'}`, `     - ${state}`)
  }
  if (!lines.join('\n').includes(`hallazgo-${record.findingId}-`)) {
    const start = lines.findIndex(line => line.startsWith('.. toctree::'))
    if (start < 0) throw new Error('el índice no tiene toctree')
    let lastEntry = start
    for (let i = start + 1; i < lines.length; i++) {
      const line = lines[i]!
      if (line.startsWith('   ') && !line.startsWith('   :') && line.trim()) lastEntry = i
      else if (line.trim() && !line.startsWith('   ')) break
    }
    lines.splice(lastEntry + 1, 0, `   ${documentName}`)
  }
  return lines.join('\n')
}

/**
 * Añade la entrada al `index.rst` de la iniciativa. El estado sale del
 * `.rst` ya escrito; sin él, `DOCUMENTADO`. `true` si el índice cambió.
 */
export function addToInitiativeIndex(record: FindingRecord): boolean {
  const target = findingFile(record)
  const folder = dirname(target)
  const indexFile = join(folder, 'index.rst')
  const existing = globSync(`hallazgo-${record.findingId}-*.rst`, { cwd: folder }).sort()[0]
  const document = existing ? join(folder, existing) : target
  const state = existsSync(document) && /^\s*:estado:\s*resuelto\b/im.test(readFileSync(document, 'utf8'))
    ? 'RESUELTO'
    : 'DOCUMENTADO'
  const before = readFileSync(indexFile, 'utf8')
  const after = addIndexEntry(before, record, basename(document, '.rst'), state)
  if (after === before) return false
  writeFileSync(indexFile, after)
  return true
}

export type PublishEntry = { id: string; resolvedIn?: string; body?: string }
export type PublishPlan = { jobs: string[]; steps: string[][] }

/**
 * Publicar N hallazgos con los instrumentos del proveedor:
 *
 * 1. cada render es un trabajo independiente de `run-task-pool`, lanzado con
 *    `thyrox-bg` para que el primer plano quede libre;
 * 2. el índice tiene un solo escritor, y espera a que los renders asienten
 *    con la arista `--after-ok` de `wait-jobs`;
 * 3. `wait-jobs dispatch` mueve la cadena sin bloquear. Quien publica recoge
 *    con `wait-jobs wait` en segundo plano.
 *
 * El registro de las filas NO entra aquí: el store tiene un solo escritor, y
 * la fila existe antes de que haya nada que renderizar.
 */
export function buildPublishPlan(entries: PublishEntry[], options: { runDir: string; name: string }): PublishPlan {
  const jobs = entries.map(entry =>
    ['bash bin/finding rst', entry.id,
      ...(entry.resolvedIn ? ['--resolved-in', entry.resolvedIn] : []),
      ...(entry.body ? ['--body', entry.body] : [])].join(' '))
  const render = `${options.name}-render`
  const index = `${options.name}-index`
  const steps = [
    ['bash', 'bin/thyrox-bg', 'start', render, '--grace', '0', '--', 'bash', 'bin/run-task-pool', join(options.runDir, 'render.jobs')],
    ['bash', 'bin/thyrox-bg', 'register', render],
    ['bash', 'bin/wait-jobs', 'register', index, join(options.runDir, 'index.log'),
      '--after-ok', render, '--run', `bash bin/finding index ${entries.map(e => e.id).join(' ')}`],
    ['bash', 'bin/wait-jobs', 'dispatch'],
  ]
  return { jobs, steps }
}

